.volumeControl[data-muted="true"] .volumeSlider,
.volumeControl[data-muted="true"] .volumeValue {
  opacity: 0.42;
}

.volumeSlider {
  width: 72px;
  height: 20px;
  margin: 0 8px;
  accent-color: #c4a46a;
  cursor: pointer;
  transition: opacity 160ms ease;
}

.volumeSlider:focus-visible {
  outline: 2px solid rgba(196, 164, 106, 0.7);
  outline-offset: 2px;
}

.volumeValue {
  width: 34px;
  margin-right: 6px;
  color: var(--muted);
  font-family: var(--font-geist-mono), monospace;
  font-size: 11px;
  line-height: 1;
  text-align: right;
  transition: opacity 160ms ease;
}

.shopkeeperStoreTabs {
  display: flex;
  align-self: stretch;
}

.shopkeeperStoreTabs button {
  min-width: 88px;
  padding: 0 13px;
  border: 0;
  border-bottom: 2px solid transparent;
  background: transparent;
  color: #777a74;
  font-family: var(--font-geist-mono), monospace;
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  cursor: pointer;
}

.shopkeeperStoreTabs button[aria-pressed="true"] {
  border-bottom-color: #d6a33f;
  color: #e2bf72;
  background: linear-gradient(180deg, transparent, rgba(210, 163, 74, 0.08));
}

.gameCard {
  position: relative;
}

.gameCard::after {
  position: absolute;
  right: 14px;
  bottom: 16px;
  display: grid;
  width: 22px;
  height: 22px;
  place-items: center;
  border: 1px solid #83c999;
  background: #17251b
