  content: "";
  font-size: 15px;
  line-height: 1;
}

.gameCard[data-on="false"]::after {
  border-color: #969d9c;
  background: transparent;
  content: "";
}

.controls button {
  min-height: 38px;
  padding: 0 11px;
  border: 1px solid var(--line);
  background: transparent;
  color: var(--muted);
